17	  private readonly _systemDark = signal<boolean>(this._mediaQuery()?.matches ?? false);
18	
19	  /** The explicit choice, or null while the user has not chosen (system theme applies). */
20	  readonly choice = this._choice.asReadonly();
21	  readonly isDark = computed(() => (this._choice() ?? (this._systemDark() ? 'dark' : 'light')) === 'dark');
22	
23	  constructor() {
24	    const media = this._mediaQuery();
25	    if (media) {
26	      media.addEventListener('change', (event) => this._systemDark.set(event.matches));
27	    }
28	
