import { pathToFileURL } from 'node:url';

const repo = 'D:/Repos/angular-jig';
const { serveStatic, launchChromium } = await import(pathToFileURL(`${repo}/harness/playwright/serve-and-visit.mjs`).href);
const { assertResponsive } = await import(pathToFileURL(`${repo}/harness/gate/check-responsive.mjs`).href);

const srv = await serveStatic(`${repo}/dist/angular-jig/browser`, { spaFallback: true });
const browser = await launchChromium();
const results = [];
const check = (name, pass, detail = '') => {
  results.push(pass);
  console.log(`${pass ? 'PASS' : 'FAIL'} ${name}${detail ? ` :: ${detail}` : ''}`);
